// Converts skill-engine (Mantle) ordered-block steps into the canvas graph.
//
// Reuses the flow-graph builder (`createFlowNodesFromFlowSteps`) by first
// mapping the v2 step wire dumps onto its v1 FlowStep shape, then upgrading
// the produced nodes where v1 has no equivalent concept:
// - `autonomous` steps become AUTONOMOUS nodes (v1 would drop them as noop),
// - `execute` steps become tool-call nodes instead of generic custom actions.
import { CallType, FlowNodeType, type FlowEdge, type FlowNode, type SkillBlock } from "../types";
import { createFlowNodesFromFlowSteps } from "./flow-import";
import type { FlowStep } from "./flow-validation";

const END_STEP_ID = "END";

interface StepUpgradeIndex {
  /** Autonomous step id → display label derived from its instructions. */
  autonomousLabels: Map<string, string>;
  /** Execute step id → tool name. */
  executeTools: Map<string, string>;
  /** set_memory step ids — relabelled from the v1 "Set Slots" wording. */
  setMemorySteps: Set<string>;
}

function asString(value: unknown): string | undefined {
  return typeof value === "string" ? value : undefined;
}

function autonomousLabel(instructions: string | undefined, stepId: string): string {
  const firstLine = instructions?.split("\n", 1)[0]?.trim();
  if (!firstLine) return stepId;
  return firstLine.length > 60 ? `${firstLine.slice(0, 57)}…` : firstLine;
}

function mapNext(next: unknown): FlowStep["next"] {
  if (typeof next === "string") return next;
  if (!Array.isArray(next)) return undefined;
  const branches: ({ if: string; then: string } | { else: string })[] = [];
  for (const branch of next) {
    if (typeof branch !== "object" || branch === null) continue;
    const target = asString((branch as Record<string, unknown>).then);
    if (target === undefined) continue;
    const condition = asString((branch as Record<string, unknown>).if);
    branches.push(condition !== undefined ? { if: condition, then: target } : { else: target });
  }
  return branches.length > 0 ? branches : undefined;
}

function mapStep(step: Record<string, unknown>, upgrades: StepUpgradeIndex): FlowStep | undefined {
  const id = asString(step.id);
  const kind = asString(step.kind);
  if (!id || id === END_STEP_ID || kind === "end") return undefined;

  const next = mapNext(step.next);
  switch (kind) {
    case "collect":
      return { id, collect: asString(step.collect), description: asString(step.description), next };
    case "action":
      return { id, action: asString(step.action), next };
    case "execute": {
      const toolName = asString(step.execute_tool) ?? "tool";
      upgrades.executeTools.set(id, toolName);
      return { id, action: toolName, next };
    }
    case "autonomous":
      upgrades.autonomousLabels.set(id, autonomousLabel(asString(step.instructions), id));
      // Placeholder action so the shared builder emits a node; upgraded below.
      return { id, action: id, next };
    case "set_memory": {
      upgrades.setMemorySteps.add(id);
      const setMemory = step.set_memory;
      const entries =
        typeof setMemory === "object" && setMemory !== null
          ? Object.entries(setMemory as Record<string, string | number | boolean | null>).map(
              ([key, value]) => ({ [key]: value }),
            )
          : [];
      return { id, set_slots: entries, next };
    }
    case "call":
      return { id, call: asString(step.call), next };
    case "link":
      return { id, link: asString(step.link) };
    case "route":
      return { id, noop: true, next };
    default:
      // Unknown future step kinds degrade to pass-through rather than crashing.
      return { id, noop: true, next };
  }
}

function upgradeNode(node: FlowNode, upgrades: StepUpgradeIndex): FlowNode {
  const label = upgrades.autonomousLabels.get(node.id);
  if (label !== undefined) {
    return { id: node.id, metadata: node.metadata, type: FlowNodeType.Autonomous, label };
  }
  const toolName = upgrades.executeTools.get(node.id);
  if (toolName !== undefined) {
    return {
      id: node.id,
      metadata: node.metadata,
      type: FlowNodeType.Call,
      callType: CallType.Tool,
      label: toolName,
    };
  }
  if (upgrades.setMemorySteps.has(node.id)) {
    return { ...node, label: "Set memory" };
  }
  return node;
}

/**
 * Builds the canvas graph for one ordered block of a skill.
 *
 * `callTargetIds` should contain every id a `call:` step may target (block
 * flow ids and skill ids) so call nodes are labelled as flow calls.
 */
export function skillBlockToGraph(
  block: SkillBlock,
  callTargetIds: string[],
): { nodes: FlowNode[]; edges: FlowEdge[] } {
  const upgrades: StepUpgradeIndex = {
    autonomousLabels: new Map(),
    executeTools: new Map(),
    setMemorySteps: new Set(),
  };

  const flowSteps = block.steps
    .map((step) => mapStep(step, upgrades))
    .filter((step): step is FlowStep => step !== undefined);

  const { nodes, edges } = createFlowNodesFromFlowSteps(
    flowSteps,
    block.ordered_block_id,
    callTargetIds,
  );
  return { nodes: nodes.map((node) => upgradeNode(node, upgrades)), edges };
}
